// k6 average-load test with an open model (arrival rate), per-endpoint thresholds and test data.
// Generated by `eos scaffold load-k6`; edit the scenarios to match real traffic (read it from your metrics).
// Run: k6 run -e BASE_URL=https://staging.example.com -e RATE=20 load/load.js
// Never against production without an agreed window; never from a laptop for numbers you will quote.
// Background: .eos/packs/ref/testing/performance-k6.md
import http from "k6/http";
import { check, sleep } from "k6";
import { SharedArray } from "k6/data";

const BASE_URL = __ENV.BASE_URL || "http://127.0.0.1:8000";
const RATE = Number(__ENV.RATE || 10); // iterations per second at the plateau
const TOKEN = __ENV.LOAD_TOKEN || ""; // a test user's token, never a real customer's

// Realistic, varied inputs (same ids every run defeat caches and hide slow paths). Generate this file from
// anonymised or synthetic data; keep it out of git if it is large. Falls back to a tiny inline set.
const ids = new SharedArray("ids", () => {
  try {
    return JSON.parse(open("./data/ids.json"));
  } catch (_) {
    return ["1", "2", "3"];
  }
});

export const options = {
  scenarios: {
    browse: {
      executor: "ramping-arrival-rate", // open model: load keeps coming even if the system slows down
      startRate: 1,
      timeUnit: "1s",
      preAllocatedVUs: 20,
      maxVUs: 200,
      stages: [
        { target: RATE, duration: "2m" }, // ramp up
        { target: RATE, duration: "5m" }, // plateau: the numbers that matter
        { target: 0, duration: "1m" }, // ramp down
      ],
    },
  },
  thresholds: {
    http_req_failed: [{ threshold: "rate<0.01", abortOnFail: true, delayAbortEval: "1m" }],
    "http_req_duration{name:list}": ["p(95)<400", "p(99)<1000"],
    "http_req_duration{name:detail}": ["p(95)<300"],
    dropped_iterations: ["count<10"], // k6 could not start iterations on time: add VUs or the system is saturated
    checks: ["rate>0.99"],
  },
};

const params = (name) => ({
  tags: { name },
  headers: TOKEN ? { Authorization: `Bearer ${TOKEN}` } : {},
});

export default function () {
  const list = http.get(`${BASE_URL}/`, params("list"));
  check(list, { "list ok": (r) => r.status === 200 });
  const id = ids[Math.floor(Math.random() * ids.length)];
  const detail = http.get(`${BASE_URL}/?id=${encodeURIComponent(id)}`, params("detail"));
  check(detail, { "detail ok": (r) => r.status < 500 });
  sleep(Math.random() * 2); // think time
}
